361	+            // An alias local to an enclosing scope is nearer than a module-level interface of the name.
362	+            let alias = visible_alias(name, args, file, scope, ctx)?;
363	+            if let Some((body, body_file, body_scope)) = &alias
364	+                && !body_scope.is_module()
365	+            {
366	+                return object_fields(body, body_file, body_scope, ctx, depth + 1);
367	+            }
368	+            let (canonical_file, canonical_name) = canonical(name, file, ctx);
369	+            if let Some(iface) = lookup_interface_including_ambient(ctx, canonical_file.as_str(), &canonical_name) {
