383	+
384	+/// The body of the alias `name` (given `args`) written in `file` within `scope`, with the file and scope it is declared
385	+/// in; `None` when no alias of the name has a body. An alias local to a function body, block or `switch` case is stored
386	+/// under its bare name, so one whose scope does not enclose the reference is not this name's declaration and may hide
387	+/// the one that is: declined.
388	+fn visible_alias(
389	+    name: &CompactString,
390	+    args: &[CollectedType],
391	+    file: &Utf8Path,
392	+    scope: &DeclarationScope,
393	+    ctx: &ResolutionContext,
394	+) -> Result<Option<(CollectedType, Utf8PathBuf, DeclarationScope)>, Declined> {
395	+    let Some(found) = alias_body_declared(name, args, file, ctx) else { return Ok(None) };
396	+    if !found.2.is_module() && (found.1 != file || !found.2.encloses(scope)) {
397	+        return Err(Declined::OutOfScope);
398	+    }
399	+    Ok(Some(found))
400	+}
401	+
402	+/// The names a key type of `Pick` or `Omit`, written in `file` within `scope`, denotes: literals, unions of them,
403	+/// `keyof` of an object read as `object_fields` reads it, and aliases of these found from the scope. A `typeof` or
404	+/// indexed-access form is read by `mapped_keys`; anything else is not a known set of names.
405	+fn key_names(
406	+    keys: &CollectedType,
407	+    file: &Utf8Path,
408	+    scope: &DeclarationScope,
409	+    ctx: &ResolutionContext,
410	+    depth: u8,
411	+) -> Result<Vec<String>, Declined> {
412	+    if depth > MAX_DEPTH {
413	+        return Err(Declined::TooDeep);
414	+    }
415	+    match keys {
416	+        CollectedType::AtFile { file: at, inner } if at != file => {
417	+            key_names(inner, at, &DeclarationScope::default(), ctx, depth + 1)
418	+        }
419	+        CollectedType::AtFile { inner, .. } => key_names(inner, file, scope, ctx, depth + 1),
420	+        CollectedType::StringLiteral(name) => Ok(vec![name.to_string()]),
421	+        CollectedType::Union(members) => {
422	+            let mut names = Vec::new();
423	+            for member in members {
424	+                names.extend(key_names(member, file, scope, ctx, depth + 1)?);
425	+            }
426	+            Ok(names)
427	+        }
428	+        CollectedType::KeyOf(target) if !matches!(target.as_ref(), CollectedType::TypeOf(_)) => {
429	+            Ok(object_fields(target, file, scope, ctx, depth + 1)?.into_iter().map(|f| f.field.name).collect())
430	+        }
431	+        CollectedType::Named { name, args } => {
432	+            let (body, body_file, body_scope) =
433	+                visible_alias(name, args, file, scope, ctx)?.ok_or(Declined::UnknownKeys)?;
434	+            key_names(&body, &body_file, &body_scope, ctx, depth + 1)
435	+        }
436	+        other => Ok(mapped_keys(other, file, ctx, depth + 1)
