444	+/// The members of an interface given `args`, which an interface with type parameters would need bound.
445	+fn interface_object(
446	+    iface: &CollectedInterface,
447	+    args: &[CollectedType],
448	+    ctx: &ResolutionContext,
449	+    depth: u8,
450	+) -> Exactness {
451	+    if !args.is_empty() {
452	+        return Err(Declined::UnknownParent);
453	+    }
454	+    let mut fields = Vec::new();
455	+    interface_fields(iface, ctx, depth + 1, &mut fields)?;
