459	+/// The members of each interface `iface` extends that the run declares, then its own: the order the checker lists them
460	+/// in. Declined when it or a parent has type parameters or lists not every member it declares, a parent is not such an
461	+/// interface, or a member is declared twice (an override, whose place in that order is not recorded).
462	+fn interface_fields(
463	+    iface: &CollectedInterface,
464	+    ctx: &ResolutionContext,
465	+    depth: u8,
466	+    out: &mut Vec<LocatedField>,
467	+) -> Result<(), Declined> {
468	+    if depth > MAX_DEPTH {
469	+        return Err(Declined::TooDeep);
470	+    }
471	+    if ctx.named_types.lookup_interface_type_params_for(iface).is_some_and(|p| !p.is_empty()) {
472	+        return Err(Declined::UnknownParent);
473	+    }
474	+    if iface.unlisted_members {
475	+        return Err(Declined::UnlistedMembers);
476	+    }
477	+    for parent in &iface.extends {
478	+        let (name, args) = match parent {
479	+            ExtendsRef::SameFile { name, type_args } => (name, type_args),
480	+            ExtendsRef::Imported { local_name, type_args, .. } => (local_name, type_args),
481	+            ExtendsRef::Builtin { .. } => return Err(Declined::UnknownParent),
482	+        };
